// ============================================================
// The COMPILE-TIME half of the contract gate (review item C018, packet.net#692).
//
// Each fixture in this directory is generated by
// tests/Packet.Node.Tests/Contract/ClientContractFixtureTests.cs from the server's own DTOs
// with the app's real wire options. Importing them here and asserting each against its
// types.ts shape means `npm run build` (tsc --noEmit) fails when types.ts declares a required
// field the server never sends, or gives one the wrong primitive kind - without anyone having
// to run vitest.
//
// WHY `Widen<T>` AND NOT A BARE `satisfies NodeConfig`: with resolveJsonModule, TypeScript
// types a JSON string as `string`, never as the literal `"Transit"`. A bare `satisfies` would
// therefore fail on every union-typed field for a reason that says nothing about the contract.
// Widen<T> relaxes exactly that - string/number/boolean literal types widen to their base -
// and nothing else, so a missing field or a wrong kind still fails here. Union MEMBERSHIP is
// checked at runtime instead, by contract.test.ts, against the server's own closed sets.
import type {
  AppPackage, AvailableApp, DoctorReport, HeadEndKeyupResult, HeadEndScan, HeardStation,
  InstallOutcome, LinkStats, LoginResult, ModemScan, MonitorEvent, NetRomRoutingSnapshot, NodeApp,
  NinoModeCatalogue, NodeConfig, NodeStatus, PeerCapability, PingResult, PortStatus,
  RadioScanResult, RadioStatus,
  ReconcileResult, RegisterCompleteResponse, RigModelCatalogue, RigScan, RigStatus, SessionInfo,
  SetupResult, SetupState, SoundModemQualitySnapshot, SystemInfo, TailscaleStatus,
  TotpEnrollBeginResponse, TotpEnrollCompleteResponse, TotpEnrollState, TuningEvent,
  TuningSessionInfo, UserSummary, ValidationProblem, WebAuthnCredential,
} from "@/lib/types";

import appPackage from "./AppPackage.json";
import availableApp from "./AvailableApp.json";
import doctorReport from "./DoctorReport.json";
import headEndKeyupResult from "./HeadEndKeyupResult.json";
import headEndScan from "./HeadEndScan.json";
import heardStation from "./HeardStation.json";
import installOutcome from "./InstallOutcome.json";
import linkStats from "./LinkStats.json";
import loginResult from "./LoginResult.json";
import modemScan from "./ModemScan.json";
import monitorEvent from "./MonitorEvent.json";
import netRomRoutingSnapshot from "./NetRomRoutingSnapshot.json";
import ninoModeCatalogue from "./NinoModeCatalogue.json";
import nodeApp from "./NodeApp.json";
import nodeConfig from "./NodeConfig.json";
import nodeStatus from "./NodeStatus.json";
import peerCapability from "./PeerCapability.json";
import pingResult from "./PingResult.json";
import portStatus from "./PortStatus.json";
import radioScanResult from "./RadioScanResult.json";
import radioStatus from "./RadioStatus.json";
import reconcileResult from "./ReconcileResult.json";
import registerCompleteResponse from "./RegisterCompleteResponse.json";
import rigModelCatalogue from "./RigModelCatalogue.json";
import rigScan from "./RigScan.json";
import rigStatus from "./RigStatus.json";
import sessionInfo from "./SessionInfo.json";
import setupResult from "./SetupResult.json";
import setupState from "./SetupState.json";
import soundModemQuality from "./SoundModemQualitySnapshot.json";
import systemInfo from "./SystemInfo.json";
import tailscaleStatus from "./TailscaleStatus.json";
import totpEnrollBegin from "./TotpEnrollBeginResponse.json";
import totpEnrollComplete from "./TotpEnrollCompleteResponse.json";
import totpEnrollState from "./TotpEnrollState.json";
import tuningEvent from "./TuningEvent.json";
import tuningSessionInfo from "./TuningSessionInfo.json";
import userSummary from "./UserSummary.json";
import validationProblem from "./ValidationProblem.json";
import webAuthnCredential from "./WebAuthnCredential.json";

/** Widen string/number/boolean literal types to their base, recursively; leave everything
 *  else (optionality, nullability, structure, arrays) exactly as declared. */
type Widen<T> =
  T extends string ? string :
  T extends number ? number :
  T extends boolean ? boolean :
  // eslint-disable-next-line @typescript-eslint/no-unsafe-function-type
  T extends Function ? T :
  T extends readonly (infer E)[] ? Widen<E>[] :
  T extends object ? { [K in keyof T]: Widen<T[K]> } :
  T;

export const CONTRACT = {
  appPackage: appPackage satisfies Widen<AppPackage>[],
  availableApp: availableApp satisfies Widen<AvailableApp>[],
  doctorReport: doctorReport satisfies Widen<DoctorReport>,
  headEndKeyupResult: headEndKeyupResult satisfies Widen<HeadEndKeyupResult>,
  headEndScan: headEndScan satisfies Widen<HeadEndScan>,
  heardStation: heardStation satisfies Widen<HeardStation>[],
  installOutcome: installOutcome satisfies Widen<InstallOutcome>,
  linkStats: linkStats satisfies Widen<LinkStats>[],
  loginResult: loginResult satisfies Widen<LoginResult>,
  modemScan: modemScan satisfies Widen<ModemScan>,
  monitorEvent: monitorEvent satisfies Widen<MonitorEvent>[],
  netRomRoutingSnapshot: netRomRoutingSnapshot satisfies Widen<NetRomRoutingSnapshot>,
  ninoModeCatalogue: ninoModeCatalogue satisfies Widen<NinoModeCatalogue>,
  nodeApp: nodeApp satisfies Widen<NodeApp>[],
  nodeConfig: nodeConfig satisfies Widen<NodeConfig>,
  nodeStatus: nodeStatus satisfies Widen<NodeStatus>,
  peerCapability: peerCapability satisfies Widen<PeerCapability>[],
  pingResult: pingResult satisfies Widen<PingResult>,
  portStatus: portStatus satisfies Widen<PortStatus>[],
  radioScanResult: radioScanResult satisfies Widen<RadioScanResult>[],
  radioStatus: radioStatus satisfies Widen<RadioStatus>[],
  reconcileResult: reconcileResult satisfies Widen<ReconcileResult>,
  registerCompleteResponse: registerCompleteResponse satisfies Widen<RegisterCompleteResponse>,
  rigModelCatalogue: rigModelCatalogue satisfies Widen<RigModelCatalogue>,
  rigScan: rigScan satisfies Widen<RigScan>,
  rigStatus: rigStatus satisfies Widen<RigStatus>[],
  sessionInfo: sessionInfo satisfies Widen<SessionInfo>[],
  setupResult: setupResult satisfies Widen<SetupResult>,
  setupState: setupState satisfies Widen<SetupState>,
  soundModemQuality: soundModemQuality satisfies Widen<SoundModemQualitySnapshot>,
  systemInfo: systemInfo satisfies Widen<SystemInfo>,
  tailscaleStatus: tailscaleStatus satisfies Widen<TailscaleStatus>,
  totpEnrollBegin: totpEnrollBegin satisfies Widen<TotpEnrollBeginResponse>,
  totpEnrollComplete: totpEnrollComplete satisfies Widen<TotpEnrollCompleteResponse>,
  totpEnrollState: totpEnrollState satisfies Widen<TotpEnrollState>,
  tuningEvent: tuningEvent satisfies Widen<TuningEvent>[],
  tuningSessionInfo: tuningSessionInfo satisfies Widen<TuningSessionInfo>,
  userSummary: userSummary satisfies Widen<UserSummary>[],
  validationProblem: validationProblem satisfies Widen<ValidationProblem>,
  webAuthnCredential: webAuthnCredential satisfies Widen<WebAuthnCredential>[],
};
